/* AMC8 2003 #21 Problem */
size(2inch,1inch);
draw((0,0)--(31,0)--(16,8)--(6,8)--cycle);
draw((11,8)--(11,0), linetype("8 4"));
draw((11,1)--(12,1)--(12,0));
label("$A$", (0,0), SW);
label("$D$", (31,0), SE);
label("$B$", (6,8), NW);
label("$C$", (16,8), NE);
